{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PRESENT",
      "chunk_id": "text_0",
      "quote": "The effects of waiting time for outpatient psychotherapeutic interventions on patientreported outcomes in adolescents and adults with eating disorders: a systematic review and meta-analysis",
      "reason": "The title explicitly labels the work as a “systematic review and meta-analysis,” identifying it as a systematic review."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_0",
      "quote": "The effects of waiting time for outpatient psychotherapeutic interventions on patientreported outcomes in adolescents and adults with eating disorders",
      "reason": "The title provides key objective information, specifying the exposure (waiting time for outpatient psychotherapeutic interventions), the outcome (patient-reported outcomes), and the population (adolescents and adults with eating disorders)."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence for the title does not report any supplementary information such as analysis method details beyond “meta-analysis,” included study designs, update status, or living-review status."
    }
  ],
  "confidence": 82
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PARTIAL",
      "chunk_id": "text_1",
      "quote": "Participants entered the waiting period with high EDE-Q Global Scores, ranging from 3.08 to 4.65 across studies.",
      "reason": "Provides some description of the current state of knowledge (high baseline eating disorder pathology during the waiting period), but does not explicitly describe important uncertainties or gaps in existing knowledge in the introduction/rationale."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PARTIAL",
      "chunk_id": "text_1",
      "quote": "Based on our results, waiting in waitlist control groups represents a period during which substantial eating disorder pathology and associated distress persist without therapeutic intervention. Further research is needed to better understand the effects of waiting time for regular eating disorder treatment outside a study setting.",
      "reason": "Explains the importance/need in terms of the persistence of pathology and the call for further research, but does not clearly justify the review itself (e.g., why a new review is needed now) as part of existing knowledge."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence found that, when similar systematic reviews exist, the need for the current review is explained with updates/replications and citations to previous systematic reviews."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence found describing a proposed mechanism of action of the intervention (this review focuses on waiting time/control conditions rather than a described mechanistic rationale)."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence found that a logic model was used to show hypothesised relationships between intervention components and outcomes."
    }
  ],
  "confidence": 45
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The research question 'What are the effects of waiting time for outpatient psychotherapeutic interventions on PROs in adolescents and adults with AN, BN, BED and OSFED' was formulated using the Population, Exposure, Comparator, Outcome (PECO) framework (Additional file 1).",
      "reason": "The review’s objective/research question is explicitly stated and formulated using the PECO framework."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Although PECO framework is mentioned, the planned comparisons for intervention effects (e.g., explicit comparator statement structured as PICO or appropriate variant) are not clearly stated in the retrieved evidence."
    }
  ],
  "confidence": 74
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Studies were included if they used an empirical, quantitative design, either randomised or non-randomised, such as RCTs, clinical trials, quasi-experimental studies or cohort studies; involved adolescents (≥ 10 years, according to the World Health Organization [72] definition) and/or adults (≥ 18 years) with AN, BN, BED or OSFED, according to DSM or International Statistical Classification of Diseases and Related Health Problems (ICD) (research) criteria that were valid at the time of diagnosis, or who exceeded validated cut-off values in questionnaires or interviews ... In addition ... Sub-BN and sub-BED had to be explicitly classified as OSFED for eligibility ... The ≥ 4 weeks cut-off for the waiting period of WLCGs was chosen ... included (a) compared an active psychotherapeutic intervention group (IG) in an outpatient setting with a WLCG or a no-treatment control group, or (b) retrospectively analysed a cohort ... In addition ... reported ED-specific PROs, measured using the Children's Eating Attitudes Test (chEAT) [73], Eating Disorder Examination-Questionnaire (EDEQ) [74] or EDE-Q 6.0 [75], for all study groups separately; and reported these PROs for a minimum of two time points: (1) ... (baseline), and (2) at least once at a subsequent time point ...",
      "reason": "The text specifies eligibility-defining study characteristics, including study design, participant age and diagnostic criteria, intervention/comparator context (WLCGs vs no-treatment), outcome instruments, and follow-up/timepoint requirements."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Studies were included regardless of publication status. Both peer-reviewed and grey literature were considered. No restrictions were applied regarding publication year or language.",
      "reason": "Eligibility criteria for report characteristics are explicitly stated for publication status, publication year, and language."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence is provided describing how exclusion was distinguished between outcomes not measured versus outcome results not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence is provided specifying the groups used in each synthesis and how they link to comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "The ≥ 4 weeks cut-off for the waiting period of WLCGs was chosen based on the EDE-Q reference period of 28 days.... Rationales for the exclusion criteria are provided in Additional file 3.",
      "reason": "A rationale is provided for at least one notable restriction (the ≥4 weeks waiting-period cut-off), and it is stated that rationales for exclusion criteria are in Additional file 3, but the evidence does not show rationales for all notable restrictions."
    }
  ],
  "confidence": 72
}

